solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const x = Number(input[0]);

let grade: string;
if (x >= 80) grade = "A";
else if (x >= 60) grade = "B";
else if (x >= 40) grade = "C";
else grade = "D";
console.log(grade);
